<script lang="ts">
 import {invoke} from '@tauri-apps/api/core';
 import {Download,ExternalLink} from 'lucide-svelte';
 import FileIcon from './FileIcon.svelte';
 import {fileDate,fileSize,fileLocation,fileKind,type DriveItem} from './files';
 let {items,ownId,onLocate,selected='',search=false,view='list',selection=null,onToggle=()=>{},selectionDisabled=false}:{items:DriveItem[];ownId:string;onLocate:(item:DriveItem)=>void;selected?:string;search?:boolean;view?:'list'|'icons';selection?:string[]|null;onToggle?:(item:DriveItem,shift:boolean)=>void;selectionDisabled?:boolean}=$props();
 let busy=$state(''),error=$state(''),notice=$state('');
 async function action(item:DriveItem,download:boolean){if(busy)return;busy=item.id;error='';notice='';try{if(download){const saved=await invoke<boolean>('files_download',{ownId,itemId:item.id});notice=saved?`${item.name} downloaded.`:'Download cancelled.';}else await invoke('files_open',{ownId,itemId:item.id});}catch(e){error=String(e);}finally{busy='';}}
</script>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
<div class="file-results"><div class="file-list" class:icon-grid={view==='icons'} class:selectable={selection!==null} aria-label={search?'OneDrive search results':'OneDrive items'}>
 {#if view==='list'&&items.length}<div class="column-headings" aria-hidden="true">{#if selection!==null}<span></span>{/if}<span>Name</span><span>Type</span><span>Modified</span><span>Size</span><span>Actions</span></div>{/if}
 {#each items as item(item.id)}<article class:selected={selected===item.id||selection?.includes(item.id)} aria-label={item.name}>
 {#if selection!==null}<input type="checkbox" aria-label={`Select ${item.name}`} checked={selection.includes(item.id)} disabled={selectionDisabled||item.shortcut} onclick={event=>onToggle(item,event.shiftKey)}/>{/if}
 <button class="file-name" title={item.name} onclick={()=>item.shortcut?action(item,false):onLocate(item)}><FileIcon {item} size={view==='icons'?48:22}/><span><strong>{item.name}</strong>{#if search}<small>{fileLocation(item)} · {item.owner}</small>{/if}{#if item.shortcut}<small>Shared shortcut</small>{/if}</span></button>
 <span class="file-type">{fileKind(item).label}</span><span class="modified">{fileDate(item.modified)}</span><span class="file-size">{item.folder?'—':fileSize(item.size)}</span>
 <div class="actions"><button disabled={!!busy} title="Open in browser" aria-label={`Open ${item.name} in browser`} onclick={()=>action(item,false)}><ExternalLink size={15}/><span>Open</span></button>{#if !item.folder&&!item.shortcut}<button disabled={!!busy} title="Download" aria-label={`Download ${item.name}`} onclick={()=>action(item,true)}><Download size={15}/><span>{busy===item.id?'Working…':'Download'}</span></button>{/if}</div>
 </article>{/each}</div></div>
